"""Compact MoE routing dispatch via cubin bundles."""

from __future__ import annotations

import torch

from kestrel_kernels.cubin_runtime import CubinFamily
from kestrel_kernels.fallback import ceil_div, is_cute_jit_enabled


_family = CubinFamily("moe_route")
_SMALL_BATCH_EXPERT_LIMIT = 64
_SMALL_BATCH_NUMEL_LIMIT = 1024
_LARGE_SCATTER_THREADS = 256
# Must equal MoeRouteCuTeConfig.materialize_warps_per_block (kernel.py): it sets
# both the grid divisor and the launch block_x here. Kept as a literal rather
# than imported to avoid pulling cutlass.cute into this runtime dispatch module.
_MATERIALIZE_WARPS_PER_BLOCK = 4
# Tried 8 warps: 1.00x at Qwen-35B-A3B/1024 (10.56/8.24 us vs
# 10.54/8.20 us for up/down); keeping 4.
_BF16_MATERIALIZE_WARPS_PER_BLOCK = 4
# Tried 128/256/512 threads at Qwen-35B-A3B/1024 on B200:
# 18.83/18.61/18.77 us for route+expand; keeping 256.
_BF16_ROUTE_MATERIALIZE_THREADS = 256

_ENABLE_JIT = is_cute_jit_enabled()
if _ENABLE_JIT:
    from scripts.precompile import cubin_bundles as _cubin_bundles


def _missing_variant_message(kind: str, variant_key: str) -> str:
    return (
        f"No {kind} cubin variant for {variant_key}. The installed "
        "kestrel-kernels wheel does not include this precompiled kernel; "
        "upgrade or reinstall kestrel-kernels, or report the missing variant."
    )


def _tag(topk_ids: torch.Tensor, topk: int, num_experts: int) -> str:
    dtype_name = "i32" if topk_ids.dtype == torch.int32 else "i64"
    return f"{dtype_name}_k{topk}_e{num_experts}"


def _sched_tag(tag: str, block_m: int) -> str:
    return f"{tag}_b{int(block_m)}"


def max_route_blocks(assignments: int, num_experts: int, block_m: int) -> int:
    if assignments <= 0:
        return 0
    active_experts = min(int(num_experts), int(assignments))
    return active_experts + (int(assignments) - active_experts) // int(block_m)


def _check_sorted_token_ids(
    sorted_token_ids: torch.Tensor,
    device: torch.device,
    *,
    min_numel: int | None = None,
) -> None:
    if (
        sorted_token_ids.device != device
        or sorted_token_ids.dtype != torch.int32
        or sorted_token_ids.ndim != 1
        or not sorted_token_ids.is_contiguous()
    ):
        raise ValueError("sorted_token_ids must be contiguous CUDA int32")
    if min_numel is not None and sorted_token_ids.numel() < int(min_numel):
        raise ValueError("sorted_token_ids capacity is smaller than the routing workload")


def _check_cu_seqlens_m(
    cu_seqlens_m: torch.Tensor,
    device: torch.device,
    num_experts: int,
) -> None:
    if (
        cu_seqlens_m.device != device
        or cu_seqlens_m.dtype != torch.int32
        or cu_seqlens_m.ndim != 1
        or cu_seqlens_m.numel() != int(num_experts) + 1
        or not cu_seqlens_m.is_contiguous()
    ):
        raise ValueError("cu_seqlens_m must be contiguous int32 with shape [num_experts + 1]")


def _check_cumsum_buffer(
    cumsum_buffer: torch.Tensor | None,
    device: torch.device,
    num_experts: int,
    *,
    required_for: str = "routing",
) -> None:
    if (
        cumsum_buffer is None
        or cumsum_buffer.device != device
        or cumsum_buffer.dtype != torch.int32
        or cumsum_buffer.ndim != 1
        or cumsum_buffer.numel() < int(num_experts)
        or not cumsum_buffer.is_contiguous()
    ):
        raise ValueError(
            "cumsum_buffer must be contiguous int32 with length >= num_experts "
            f"for {required_for}"
        )


def _check_block_schedule(
    block_offsets: torch.Tensor,
    block_expert_ids: torch.Tensor,
    device: torch.device,
    *,
    block_m: int,
    assignments: int | None = None,
    num_experts: int | None = None,
) -> None:
    if int(block_m) <= 0:
        raise ValueError("block_m must be positive")
    if (
        block_offsets.device != device
        or block_expert_ids.device != device
        or block_offsets.dtype != torch.int32
        or block_expert_ids.dtype != torch.int32
        or block_offsets.ndim != 1
        or block_expert_ids.ndim != 1
        or block_offsets.numel() < block_expert_ids.numel() + 2
        or not block_offsets.is_contiguous()
        or not block_expert_ids.is_contiguous()
    ):
        raise ValueError("block schedule buffers must be contiguous int32 1D tensors")
    if assignments is None:
        return
    if num_experts is None:
        raise ValueError("num_experts is required when checking block schedule capacity")
    required_blocks = max_route_blocks(int(assignments), int(num_experts), int(block_m))
    if block_expert_ids.numel() < required_blocks or block_offsets.numel() < required_blocks + 2:
        raise ValueError(
            "block schedule capacity is smaller than the routing worst-case "
            f"({required_blocks} blocks)"
        )


def _check_row_scale(row_scale: torch.Tensor, device: torch.device, rows: int) -> None:
    if (
        row_scale.device != device
        or row_scale.dtype != torch.float32
        or row_scale.ndim != 1
        or row_scale.numel() < int(rows)
        or not row_scale.is_contiguous()
    ):
        raise ValueError("row_scale must be contiguous fp32 with length >= sorted_token_ids")


def _check_mxfp8_scale_tensor(
    name: str,
    scale: torch.Tensor,
    device: torch.device,
    *,
    shape_message: str,
    k_tiles: int | None = None,
    min_m_tiles: int | None = None,
) -> None:
    e8m0_dtype = getattr(torch, "float8_e8m0fnu", None)
    if scale.device != device:
        raise ValueError(f"{name} must be on the same CUDA device")
    if e8m0_dtype is not None and scale.dtype != e8m0_dtype:
        raise ValueError(f"{name} must be torch.float8_e8m0fnu")
    if (
        scale.ndim != 4
        or int(scale.shape[0]) != 1
        or int(scale.shape[3]) != 512
        or (k_tiles is not None and int(scale.shape[2]) != int(k_tiles))
        or (min_m_tiles is not None and int(scale.shape[1]) < int(min_m_tiles))
    ):
        raise ValueError(shape_message)
    if scale.stride(-1) != 1:
        raise ValueError(f"{name} must be contiguous in the 512B atom")


def _check_mxfp8_scale_pair(
    source_scale: torch.Tensor,
    routed_scale: torch.Tensor,
    device: torch.device,
) -> None:
    _check_mxfp8_scale_tensor(
        "source_scale",
        source_scale,
        device,
        shape_message="source_scale must have shape [1, source_m_tiles, ceil(K/128), 512]",
    )
    _check_mxfp8_scale_tensor(
        "routed_scale",
        routed_scale,
        source_scale.device,
        shape_message="routed_scale must have shape [1, routed_m_tiles, ceil(K/128), 512]",
        k_tiles=int(source_scale.shape[2]),
    )


