def moe_route_topk(
    topk_ids: torch.Tensor,
    num_experts: int,
    sorted_token_ids: torch.Tensor,
    cu_seqlens_m: torch.Tensor,
    cumsum_buffer: torch.Tensor,
) -> None:
    """Build exact expert-major top-k assignment routing.

    Outputs:
      sorted_token_ids: length T*K, values are flat assignment ids
      cu_seqlens_m: length E+1, exact per-expert prefix sums
    """
    if topk_ids.device.type != "cuda":
        raise ValueError("topk_ids must be a CUDA tensor")
    if not topk_ids.is_contiguous() or topk_ids.ndim != 2:
        raise ValueError("topk_ids must be a contiguous 2D tensor [num_tokens, top_k]")
    if topk_ids.dtype not in (torch.int32, torch.int64):
        raise ValueError("topk_ids must be int32 or int64")
    _check_sorted_token_ids(sorted_token_ids, topk_ids.device, min_numel=topk_ids.numel())
    _check_cu_seqlens_m(cu_seqlens_m, topk_ids.device, int(num_experts))
    _check_cumsum_buffer(cumsum_buffer, topk_ids.device, int(num_experts))

    topk = int(topk_ids.shape[1])
    numel = int(topk_ids.numel())

    tag = _tag(topk_ids, topk, int(num_experts))
    small = (
        int(num_experts) <= _SMALL_BATCH_EXPERT_LIMIT
        and numel < _SMALL_BATCH_NUMEL_LIMIT
    )
    needed_keys = (
        (("small", f"small_{tag}", None),)
        if small
        else (
            ("large_align", f"large_align_{tag}", None),
            ("large_scatter", f"large_scatter_{tag}", None),
        )
    )
    _ensure_variants(needed_keys, topk_ids, int(num_experts))

    sorted_view = sorted_token_ids[:numel]
    if small:
        _family.resolve_dispatch(topk_ids, variant_key=f"small_{tag}", grid_x=1)(
            topk_ids,
            sorted_view,
            cu_seqlens_m,
        )
        return

    _family.resolve_dispatch(topk_ids, variant_key=f"large_align_{tag}", grid_x=1)(
        topk_ids,
        cu_seqlens_m,
        cumsum_buffer[: int(num_experts)],
    )
    scatter_blocks = ceil_div(numel, _LARGE_SCATTER_THREADS)
    _family.resolve_dispatch(
        topk_ids, variant_key=f"large_scatter_{tag}", grid_x=scatter_blocks
    )(
        topk_ids,
        sorted_view,
        cumsum_buffer[: int(num_experts)],
    )


def moe_route_topk_materialize_bf16(
    *,
    topk_ids: torch.Tensor,
    num_experts: int,
    A: torch.Tensor,
    sorted_token_ids: torch.Tensor,
    cu_seqlens_m: torch.Tensor,
    cumsum_buffer: torch.Tensor,
    A_routed: torch.Tensor,
    row_scale: torch.Tensor,
) -> None:
    """Build an expert-major route and expand token-major BF16 rows into it."""
    if topk_ids.device.type != "cuda":
        raise ValueError("topk_ids must be a CUDA tensor")
    if not topk_ids.is_contiguous() or topk_ids.ndim != 2:
        raise ValueError("topk_ids must be a contiguous 2D tensor [num_tokens, top_k]")
    if topk_ids.dtype not in (torch.int32, torch.int64):
        raise ValueError("topk_ids must be int32 or int64")
    if (
        A.device != topk_ids.device
        or A.dtype != torch.bfloat16
        or A.ndim != 2
        or int(A.shape[0]) != int(topk_ids.shape[0])
        or int(A.shape[1]) % 8 != 0
        or not A.is_contiguous()
    ):
        raise ValueError("A must be contiguous CUDA BF16 [num_tokens, K]")
    numel = int(topk_ids.numel())
    _check_sorted_token_ids(sorted_token_ids, A.device, min_numel=numel)
    _check_cu_seqlens_m(cu_seqlens_m, A.device, int(num_experts))
    _check_cumsum_buffer(cumsum_buffer, A.device, int(num_experts))
    if (
        A_routed.device != A.device
        or A_routed.dtype != torch.bfloat16
        or A_routed.ndim != 2
        or int(A_routed.shape[0]) < numel
        or int(A_routed.shape[1]) != int(A.shape[1])
        or not A_routed.is_contiguous()
    ):
        raise ValueError("A_routed must be contiguous BF16 [assignments, K]")
    _check_row_scale(row_scale, A.device, numel)

    topk = int(topk_ids.shape[1])
    small = (
        int(num_experts) <= _SMALL_BATCH_EXPERT_LIMIT
        and numel < _SMALL_BATCH_NUMEL_LIMIT
    )
    if small:
        moe_route_topk(
            topk_ids,
            num_experts,
            sorted_token_ids,
            cu_seqlens_m,
            cumsum_buffer,
        )
        moe_route_materialize_bf16(
            kind="up",
            A=A,
            topk_weights=row_scale,
            sorted_token_ids=sorted_token_ids[:numel],
            cu_seqlens_m=cu_seqlens_m,
            A_routed=A_routed,
            row_scale=row_scale,
            top_k=topk,
            num_experts=num_experts,
        )
        return

    tag = _tag(topk_ids, topk, int(num_experts))
    align_key = f"large_align_{tag}"
    route_key = _route_materialize_bf16_up_key(
        K=int(A.shape[1]), topk_ids=topk_ids, num_experts=int(num_experts)
    )
    _ensure_variants(
        (("large_align", align_key, None),), topk_ids, int(num_experts)
    )
    _ensure_route_materialize_bf16_up_variant(
        route_key,
        topk_ids=topk_ids,
        A=A,
        num_experts=int(num_experts),
    )
    _family.resolve_dispatch(topk_ids, variant_key=align_key, grid_x=1)(
        topk_ids,
        cu_seqlens_m,
        cumsum_buffer[: int(num_experts)],
    )
    assignments_per_cta = _BF16_ROUTE_MATERIALIZE_THREADS // 32
    scatter_blocks = ceil_div(numel, assignments_per_cta)
    _family.resolve_dispatch(
        topk_ids, variant_key=route_key, grid_x=scatter_blocks
    )(
        topk_ids,
        A,
        sorted_token_ids[:numel],
        cumsum_buffer[: int(num_experts)],
        A_routed[:numel],
        row_scale[:numel],
    )


def moe_route_topk_schedule(
    topk_ids: torch.Tensor,
    num_experts: int,
    sorted_token_ids: torch.Tensor,
    block_offsets: torch.Tensor,
    block_expert_ids: torch.Tensor,
    *,
    block_m: int,
    cu_seqlens_m: torch.Tensor | None = None,
    cumsum_buffer: torch.Tensor | None = None,
) -> None:
    """Build expert-major top-k assignments plus compact block schedule.

    If cu_seqlens_m is provided, the route kernel also writes exact per-expert
    offsets for tcgen kernels. Otherwise this is the schedule-only form used by
    compact routed GEMM kernels.
    """
    if topk_ids.device.type != "cuda":
        raise ValueError("topk_ids must be a CUDA tensor")
    if not topk_ids.is_contiguous() or topk_ids.ndim != 2:
        raise ValueError("topk_ids must be a contiguous 2D tensor [num_tokens, top_k]")
    if topk_ids.dtype not in (torch.int32, torch.int64):
        raise ValueError("topk_ids must be int32 or int64")
    _check_sorted_token_ids(sorted_token_ids, topk_ids.device, min_numel=topk_ids.numel())
    if cu_seqlens_m is not None:
        _check_cu_seqlens_m(cu_seqlens_m, topk_ids.device, int(num_experts))

    topk = int(topk_ids.shape[1])
    numel = int(topk_ids.numel())
    _check_block_schedule(
        block_offsets,
        block_expert_ids,
        topk_ids.device,
        block_m=int(block_m),
        assignments=numel,
        num_experts=int(num_experts),
    )

    tag = _tag(topk_ids, topk, int(num_experts))
    small = (
        int(num_experts) <= _SMALL_BATCH_EXPERT_LIMIT
        and numel < _SMALL_BATCH_NUMEL_LIMIT
    )
    scheduled = _sched_tag(tag, int(block_m))
    if small:
        phase = "small_sched" if cu_seqlens_m is not None else "small_sched_only"
        key = f"{phase}_{scheduled}"
        _ensure_variants(
            ((phase, key, int(block_m)),),
            topk_ids,
            int(num_experts),
        )
        _family.resolve_dispatch(
            topk_ids, variant_key=key, grid_x=1
        )(
            topk_ids,
            sorted_token_ids[:numel],
            cu_seqlens_m if cu_seqlens_m is not None else block_offsets,
            block_offsets,
            block_expert_ids,
        )
        return

    _check_cumsum_buffer(
        cumsum_buffer,
        topk_ids.device,
        int(num_experts),
        required_for="large schedule routing",
    )

    align_phase = (
        "large_align_sched" if cu_seqlens_m is not None else "large_align_sched_only"
    )
    align_key = f"{align_phase}_{scheduled}"
    _ensure_variants(
        (
            (align_phase, align_key, int(block_m)),
            ("large_scatter", f"large_scatter_{tag}", None),
        ),
        topk_ids,
        int(num_experts),
    )
    _family.resolve_dispatch(
        topk_ids, variant_key=align_key, grid_x=1
    )(
        topk_ids,
        cu_seqlens_m if cu_seqlens_m is not None else cumsum_buffer[: int(num_experts)],
        cumsum_buffer[: int(num_experts)],
        block_offsets,
        block_expert_ids,
    )
    scatter_blocks = ceil_div(numel, _LARGE_SCATTER_THREADS)
    _family.resolve_dispatch(
        topk_ids, variant_key=f"large_scatter_{tag}", grid_x=scatter_blocks
    )(
        topk_ids,
        sorted_token_ids[:numel],
        cumsum_buffer[: int(num_experts)],
    )


def moe_route_topk_schedule_copy_mxfp8_scale(
    *,
    topk_ids: torch.Tensor,
    num_experts: int,
    sorted_token_ids: torch.Tensor,
    block_offsets: torch.Tensor,
    block_expert_ids: torch.Tensor,
    source_scale: torch.Tensor,
    routed_scale: torch.Tensor,
    block_m: int,
    cu_seqlens_m: torch.Tensor,
    cumsum_buffer: torch.Tensor,
) -> None:
    """Build the compact route schedule and route token-major FC1 MXFP8 scales."""
    if topk_ids.device.type != "cuda":
        raise ValueError("topk_ids must be a CUDA tensor")
    if not topk_ids.is_contiguous() or topk_ids.ndim != 2:
        raise ValueError("topk_ids must be a contiguous 2D tensor [num_tokens, top_k]")
    if topk_ids.dtype not in (torch.int32, torch.int64):
        raise ValueError("topk_ids must be int32 or int64")
    topk = int(topk_ids.shape[1])
    numel = int(topk_ids.numel())
    small = (
        int(num_experts) <= _SMALL_BATCH_EXPERT_LIMIT
        and numel < _SMALL_BATCH_NUMEL_LIMIT
    )
    if small:
        moe_route_topk_schedule(
            topk_ids,
            num_experts,
            sorted_token_ids,
            block_offsets,
            block_expert_ids,
            block_m=block_m,
            cu_seqlens_m=cu_seqlens_m,
            cumsum_buffer=cumsum_buffer,
        )
        moe_route_copy_mxfp8_scale(
            kind="up",
            source_scale=source_scale,
            sorted_token_ids=sorted_token_ids,
            cu_seqlens_m=cu_seqlens_m,
            block_offsets=block_offsets,
            block_expert_ids=block_expert_ids,
            routed_scale=routed_scale,
            top_k=topk,
            num_experts=num_experts,
            block_m=block_m,
        )
        return
    _check_sorted_token_ids(sorted_token_ids, topk_ids.device, min_numel=numel)
    _check_cu_seqlens_m(cu_seqlens_m, topk_ids.device, int(num_experts))
    _check_cumsum_buffer(cumsum_buffer, topk_ids.device, int(num_experts))
    _check_block_schedule(
        block_offsets,
        block_expert_ids,
        topk_ids.device,
        block_m=int(block_m),
        assignments=numel,
        num_experts=int(num_experts),
    )
    _check_mxfp8_scale_pair(source_scale, routed_scale, topk_ids.device)

    tag = _tag(topk_ids, topk, int(num_experts))
    scheduled = _sched_tag(tag, int(block_m))
    align_phase = "large_align_sched"
    align_key = f"{align_phase}_{scheduled}"
    copy_key = _schedule_copy_mxfp8_scale_key(
        K=int(source_scale.shape[2]) * 128,
        topk=topk,
        num_experts=int(num_experts),
        topk_dtype=topk_ids.dtype,
        block_m=int(block_m),
    )
    _ensure_variants(
        ((align_phase, align_key, int(block_m)),),
        topk_ids,
        int(num_experts),
    )
    _ensure_schedule_copy_mxfp8_scale_variant(
        copy_key,
        topk_ids=topk_ids,
        source_scale=source_scale,
        topk=topk,
        num_experts=int(num_experts),
        block_m=int(block_m),
    )
    _family.resolve_dispatch(topk_ids, variant_key=align_key, grid_x=1)(
        topk_ids,
        cu_seqlens_m,
        cumsum_buffer[: int(num_experts)],
        block_offsets,
        block_expert_ids,
    )
    scatter_blocks = ceil_div(numel * 8, _LARGE_SCATTER_THREADS)
    _family.resolve_dispatch(topk_ids, variant_key=copy_key, grid_x=scatter_blocks)(
        topk_ids,
        sorted_token_ids[:numel],
        cu_seqlens_m,
        cumsum_buffer[: int(num_experts)],
        source_scale,
        routed_scale,
    )


def moe_route_materialize_fp8(
    *,
    kind: str,
    A_fp8_bits: torch.Tensor,
    A_scale: torch.Tensor,
    topk_weights: torch.Tensor,
    sorted_token_ids: torch.Tensor,
    cu_seqlens_m: torch.Tensor,
    A_routed_bits: torch.Tensor,
    row_scale: torch.Tensor,
    top_k: int,
    num_experts: int,
) -> None:
    if kind not in ("up", "down"):
        raise ValueError(f"unknown MoE materialize kind {kind!r}")
    if A_fp8_bits.device.type != "cuda" or A_fp8_bits.dtype != torch.uint8:
        raise ValueError("A_fp8_bits must be a CUDA uint8 tensor")
    if A_scale.device != A_fp8_bits.device or A_scale.dtype != torch.float32:
        raise ValueError("A_scale must be a CUDA fp32 tensor on the same device")
    if topk_weights.device != A_fp8_bits.device:
        raise ValueError("topk_weights must be on the same CUDA device")
    if topk_weights.dtype not in (torch.bfloat16, torch.float32):
        raise ValueError("topk_weights must be bf16 or fp32")
    _check_sorted_token_ids(sorted_token_ids, A_fp8_bits.device)
    _check_cu_seqlens_m(cu_seqlens_m, A_fp8_bits.device, int(num_experts))
    if (
        A_routed_bits.device != A_fp8_bits.device
        or A_routed_bits.dtype != torch.uint8
        or A_routed_bits.ndim != 2
        or A_routed_bits.shape[0] < sorted_token_ids.numel()
        or A_routed_bits.shape[1] != A_fp8_bits.shape[1]
        or not A_routed_bits.is_contiguous()
    ):
        raise ValueError("A_routed_bits must be contiguous uint8 [sorted_token_ids, K]")
    _check_row_scale(row_scale, A_fp8_bits.device, sorted_token_ids.numel())
    if A_fp8_bits.ndim != 2 or int(A_fp8_bits.shape[1]) % 16 != 0:
        raise ValueError("A_fp8_bits must be 2D with K multiple of 16")

    rows = int(sorted_token_ids.numel())
    if rows == 0:
        return

    variant_key = _materialize_key(
        kind=kind,
        K=int(A_fp8_bits.shape[1]),
        topk=int(top_k),
        num_experts=int(num_experts),
        topk_weight_dtype=topk_weights.dtype,
    )
    _ensure_materialize_variant(
        variant_key,
        kind=kind,
        A_fp8_bits=A_fp8_bits,
        topk=int(top_k),
        num_experts=int(num_experts),
        topk_weight_dtype=topk_weights.dtype,
    )
    grid_x = ceil_div(rows, _MATERIALIZE_WARPS_PER_BLOCK)
    _family.resolve_dispatch(A_fp8_bits, variant_key=variant_key, grid_x=grid_x)(
        A_fp8_bits,
        A_scale,
        topk_weights,
        sorted_token_ids,
        cu_seqlens_m,
        A_routed_bits[:rows],
        row_scale[:rows],
    )


def moe_route_materialize_bf16(
    *,
    kind: str,
    A: torch.Tensor,
    topk_weights: torch.Tensor,
    sorted_token_ids: torch.Tensor,
    cu_seqlens_m: torch.Tensor,
    A_routed: torch.Tensor,
    row_scale: torch.Tensor,
    top_k: int,
    num_experts: int,
) -> None:
    if kind not in ("up", "down"):
        raise ValueError(f"unknown MoE materialize kind {kind!r}")
    if A.device.type != "cuda" or A.dtype != torch.bfloat16:
        raise ValueError("A must be a CUDA BF16 tensor")
    if A.ndim != 2 or int(A.shape[1]) % 8 != 0 or not A.is_contiguous():
        raise ValueError("A must be contiguous [rows, K] with K multiple of 8")
    if topk_weights.device != A.device:
        raise ValueError("topk_weights must be on the same CUDA device")
    if topk_weights.dtype not in (torch.bfloat16, torch.float32):
        raise ValueError("topk_weights must be bf16 or fp32")
    _check_sorted_token_ids(sorted_token_ids, A.device)
    _check_cu_seqlens_m(cu_seqlens_m, A.device, int(num_experts))
    if (
        A_routed.device != A.device
        or A_routed.dtype != torch.bfloat16
        or A_routed.ndim != 2
        or A_routed.shape[0] < sorted_token_ids.numel()
        or A_routed.shape[1] != A.shape[1]
        or not A_routed.is_contiguous()
    ):
        raise ValueError("A_routed must be contiguous BF16 [sorted_token_ids, K]")
    _check_row_scale(row_scale, A.device, sorted_token_ids.numel())

    rows = int(sorted_token_ids.numel())
    if rows == 0:
        return
    variant_key = _materialize_bf16_key(
        kind=kind,
        K=int(A.shape[1]),
        topk=int(top_k),
        num_experts=int(num_experts),
        topk_weight_dtype=topk_weights.dtype,
    )
    _ensure_materialize_bf16_variant(
        variant_key,
        kind=kind,
        A=A,
        topk=int(top_k),
        num_experts=int(num_experts),
        topk_weight_dtype=topk_weights.dtype,
    )
    grid_x = ceil_div(rows, _BF16_MATERIALIZE_WARPS_PER_BLOCK)
    _family.resolve_dispatch(A, variant_key=variant_key, grid_x=grid_x)(
        A,
        topk_weights,
        sorted_token_ids,
        cu_seqlens_m,
        A_routed[:rows],
        row_scale[:rows],
    )



def moe_route_activate_materialize_bf16(
    *,
    base_up: torch.Tensor,
    topk_weights: torch.Tensor,
    sorted_token_ids: torch.Tensor,
    cu_seqlens_m: torch.Tensor,
    A_routed: torch.Tensor,
    row_scale: torch.Tensor,
    num_experts: int,
    activation: str,
    interleaved: bool,
) -> None:
    if activation not in ("gelu", "geglu", "swiglu"):
        raise ValueError(f"unsupported MoE activation {activation!r}")
    if activation == "geglu" and interleaved:
        raise ValueError("GEGLU requires contiguous gate/up rows")
    if base_up.device.type != "cuda" or base_up.dtype != torch.bfloat16:
        raise ValueError("base_up must be a CUDA BF16 tensor")
    if (
        base_up.ndim != 2
        or int(base_up.shape[1]) % 16 != 0
        or not base_up.is_contiguous()
    ):
        raise ValueError("base_up must be contiguous [assignments, 2 * K]")
    if topk_weights.device != base_up.device:
        raise ValueError("topk_weights must be on the same CUDA device")
    if topk_weights.dtype not in (torch.bfloat16, torch.float32):
        raise ValueError("topk_weights must be bf16 or fp32")
    _check_sorted_token_ids(sorted_token_ids, base_up.device)
    _check_cu_seqlens_m(cu_seqlens_m, base_up.device, int(num_experts))
    rows = int(sorted_token_ids.numel())
    K = int(base_up.shape[1]) // 2
    if (
        A_routed.device != base_up.device
        or A_routed.dtype != torch.bfloat16
        or A_routed.ndim != 2
        or A_routed.shape[0] < rows
        or int(A_routed.shape[1]) != K
        or not A_routed.is_contiguous()
    ):
        raise ValueError("A_routed must be contiguous BF16 [sorted_token_ids, K]")
    _check_row_scale(row_scale, base_up.device, rows)
    if rows == 0:
        return

    variant_key = _activate_materialize_bf16_key(
        K=K,
        num_experts=int(num_experts),
        topk_weight_dtype=topk_weights.dtype,
        activation=activation,
        interleaved=bool(interleaved),
    )
    _ensure_activate_materialize_bf16_variant(
        variant_key,
        base_up=base_up,
        num_experts=int(num_experts),
        topk_weight_dtype=topk_weights.dtype,
        activation=activation,
        interleaved=bool(interleaved),
    )
    grid_x = ceil_div(rows, _BF16_MATERIALIZE_WARPS_PER_BLOCK)
    _family.resolve_dispatch(base_up, variant_key=variant_key, grid_x=grid_x)(
        base_up,
        topk_weights,
        sorted_token_ids,
        cu_seqlens_m,
        A_routed[:rows],
        row_scale[:rows],
    )


def moe_route_activate_quantize_materialize_fp8(
    *,
    base_up: torch.Tensor,
    topk_weights: torch.Tensor,
    sorted_token_ids: torch.Tensor,
    cu_seqlens_m: torch.Tensor,
    activation: torch.Tensor,
    A_routed_bits: torch.Tensor,
    row_scale: torch.Tensor,
    num_experts: int,
) -> None:
    rows = int(sorted_token_ids.numel())
    if rows == 0:
        return
    K = int(base_up.shape[1]) // 2

    variant_key = _activate_quant_materialize_key(
        K=K,
        num_experts=int(num_experts),
        topk_weight_dtype=topk_weights.dtype,
    )
    _ensure_activate_quant_materialize_variant(
        variant_key,
        base_up=base_up,
        num_experts=int(num_experts),
        topk_weight_dtype=topk_weights.dtype,
    )
    grid_x = ceil_div(rows, _MATERIALIZE_WARPS_PER_BLOCK)
    _family.resolve_dispatch(base_up, variant_key=variant_key, grid_x=grid_x)(
        base_up,
        topk_weights,
        sorted_token_ids,
        cu_seqlens_m,
        activation,
        A_routed_bits[:rows],
        row_scale[:rows],
    )


def moe_route_activate_quantize_mxfp8(
    *,
    base_up: torch.Tensor,
    topk_weights: torch.Tensor,
    sorted_token_ids: torch.Tensor,
    cu_seqlens_m: torch.Tensor,
    block_offsets: torch.Tensor,
    block_expert_ids: torch.Tensor,
    activation: torch.Tensor,
    A_mxfp8_bits: torch.Tensor,
    A_block_scale: torch.Tensor,
    row_scale: torch.Tensor,
    num_experts: int,
    block_m: int,
) -> None:
    rows = int(sorted_token_ids.numel())
    if rows == 0:
        return
    if base_up.device.type != "cuda" or base_up.dtype != torch.bfloat16:
        raise ValueError("base_up must be a CUDA BF16 tensor")
    if base_up.ndim != 2 or int(base_up.shape[1]) % 256 != 0 or not base_up.is_contiguous():
        raise ValueError("base_up must be contiguous [rows, 2*K] with K multiple of 128")
    K = int(base_up.shape[1]) // 2
    if (
        activation.device != base_up.device
        or activation.dtype != torch.bfloat16
        or activation.ndim != 2
        or activation.shape[0] < rows
        or int(activation.shape[1]) != K
        or not activation.is_contiguous()
    ):
        raise ValueError("activation must be contiguous BF16 [sorted_token_ids, K]")
    if topk_weights.device != base_up.device:
        raise ValueError("topk_weights must be on the same CUDA device")
    if topk_weights.dtype not in (torch.bfloat16, torch.float32):
        raise ValueError("topk_weights must be bf16 or fp32")
    _check_sorted_token_ids(sorted_token_ids, base_up.device)
    _check_cu_seqlens_m(cu_seqlens_m, base_up.device, int(num_experts))
    _check_block_schedule(
        block_offsets,
        block_expert_ids,
        base_up.device,
        block_m=int(block_m),
    )
    if (
        A_mxfp8_bits.device != base_up.device
        or A_mxfp8_bits.dtype != torch.uint8
        or A_mxfp8_bits.ndim != 2
        or A_mxfp8_bits.shape[0] < rows
        or int(A_mxfp8_bits.shape[1]) != K
        or not A_mxfp8_bits.is_contiguous()
    ):
        raise ValueError("A_mxfp8_bits must be contiguous uint8 [sorted_token_ids, K]")
    _check_mxfp8_scale_tensor(
        "A_block_scale",
        A_block_scale,
        base_up.device,
        shape_message="A_block_scale must have shape [1, padded_expert_m_tiles, ceil(K/128), 512]",
        k_tiles=ceil_div(K, 128),
        min_m_tiles=int(num_experts),
    )
    _check_row_scale(row_scale, base_up.device, rows)
    variant_key = _activate_quantize_mxfp8_key(
        K=K,
        num_experts=int(num_experts),
        topk_weight_dtype=topk_weights.dtype,
        block_m=int(block_m),
    )
    _ensure_activate_quantize_mxfp8_variant(
        variant_key,
        base_up=base_up,
        num_experts=int(num_experts),
        topk_weight_dtype=topk_weights.dtype,
        block_m=int(block_m),
    )
    chunks_per_block = ceil_div(int(block_m), _MATERIALIZE_WARPS_PER_BLOCK)
    grid_x = int(block_expert_ids.numel()) * chunks_per_block
    _family.resolve_dispatch(base_up, variant_key=variant_key, grid_x=grid_x)(
        base_up,
        topk_weights,
        sorted_token_ids,
        cu_seqlens_m,
        block_offsets,
        block_expert_ids,
        activation[:rows],
        A_mxfp8_bits[:rows],
        A_block_scale,
        row_scale[:rows],
    )


def moe_route_copy_mxfp8_scale(
    *,
    kind: str,
    source_scale: torch.Tensor,
    sorted_token_ids: torch.Tensor,
    cu_seqlens_m: torch.Tensor,
    block_offsets: torch.Tensor,
    block_expert_ids: torch.Tensor,
    routed_scale: torch.Tensor,
    top_k: int,
    num_experts: int,
    block_m: int,
) -> None:
    if kind not in ("up", "down"):
        raise ValueError(f"unknown MXFP8 scale route kind {kind!r}")
    rows = int(sorted_token_ids.numel())
    if rows == 0:
        return
    if source_scale.device.type != "cuda":
        raise ValueError("source_scale must be a CUDA tensor")
    _check_sorted_token_ids(sorted_token_ids, source_scale.device)
    _check_cu_seqlens_m(cu_seqlens_m, source_scale.device, int(num_experts))
    _check_block_schedule(
        block_offsets,
        block_expert_ids,
        source_scale.device,
        block_m=int(block_m),
    )
    _check_mxfp8_scale_pair(source_scale, routed_scale, source_scale.device)

    K = int(source_scale.shape[2]) * 128
    variant_key = _copy_mxfp8_scale_key(
        kind=kind,
        K=K,
        topk=int(top_k),
        num_experts=int(num_experts),
        block_m=int(block_m),
    )
    _ensure_copy_mxfp8_scale_variant(
        variant_key,
        kind=kind,
        source_scale=source_scale,
        topk=int(top_k),
        num_experts=int(num_experts),
        block_m=int(block_m),
    )
    chunks_per_block = ceil_div(int(block_m), _MATERIALIZE_WARPS_PER_BLOCK)
    grid_x = int(block_expert_ids.numel()) * chunks_per_block
    _family.resolve_dispatch(source_scale, variant_key=variant_key, grid_x=grid_x)(
        source_scale,
        sorted_token_ids,
        cu_seqlens_m,
        block_offsets,
        block_expert_ids,
        routed_scale,
    )


